// w4002-parse-input (PRO-84)
// Extract callback fields from W7's POST body. W4's webhook is invoked by
// w7-call-w4 (an HTTP node) which POSTs JSON.stringify({...callback fields}).
// n8n places the parsed body under $json.body for webhook nodes.
const body = $input.item.json.body || $input.item.json || {};

const required = ['token', 'action', 'nonce', 'ts_hex', 'hmac_hex', 'chat_id', 'message_id'];
for (const k of required) {
  if (body[k] == null) {
    return { json: { _abort: true, _abort_reason: 'missing field in W7 payload: ' + k, raw_body: body } };
  }
}

return { json: {
  token: String(body.token),
  action: String(body.action),
  nonce: String(body.nonce),
  ts_hex: String(body.ts_hex),
  hmac_hex: String(body.hmac_hex),
  ts_unix_seconds: body.ts_unix_seconds != null ? Number(body.ts_unix_seconds) : null,
  callback_age_seconds: body.callback_age_seconds != null ? Number(body.callback_age_seconds) : null,
  callback_query_id: body.callback_query_id || null,
  chat_id: body.chat_id,
  message_id: body.message_id,
  from_user_id: body.from_user_id != null ? body.from_user_id : null
}};

// w4003-hmac-validate (PRO-84)
// Defense-in-depth: re-validate the Telegram callback HMAC even though W7 already
// validated it. Algorithm matches w7004-hmac-validate verbatim — single source of truth
// for the callback HMAC contract (TELEGRAM_CALLBACK_SECRET). Replay window: -60s to +600s.
// Note: this is the TELEGRAM CALLBACK HMAC (truncated 32 hex chars), NOT the listener HMAC.
// The listener HMAC is computed separately in w4023-build-listener-request and uses
// W4_LISTENER_HMAC_SECRET (full 64 hex chars over raw body).
const crypto = require('crypto');

const data = $input.item.json;
if (data._abort) {
  return { json: { ...data, validated: false, reject_reason: data._abort_reason } };
}

const secret = $env.TELEGRAM_CALLBACK_SECRET;
if (!secret || secret.length < 32) {
  return { json: { ...data, validated: false, reject_reason: 'TELEGRAM_CALLBACK_SECRET missing or too short' } };
}

const payload = data.token + data.action + data.nonce + data.ts_hex;
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);

let hmac_ok = false;
try {
  hmac_ok = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(data.hmac_hex, 'hex'));
} catch (e) {
  return { json: { ...data, validated: false, reject_reason: 'hmac comparison threw: ' + e.message } };
}

if (!hmac_ok) {
  return { json: { ...data, validated: false, reject_reason: 'hmac mismatch' } };
}

if (data.ts_unix_seconds != null) {
  const now_seconds = Math.floor(Date.now() / 1000);
  const age = now_seconds - data.ts_unix_seconds;
  if (age > 600) return { json: { ...data, validated: false, reject_reason: 'callback older than 10 min (age=' + age + 's)' } };
  if (age < -60) return { json: { ...data, validated: false, reject_reason: 'callback timestamp in future (age=' + age + 's)' } };
}

return { json: { ...data, validated: true } };

// w4006-lookup-pending-dispatch (PRO-84)
// Read /miru-data/pending_callbacks.jsonl, walk in reverse to find the latest
// kind='dispatch' row matching the current token. That row was written by
// w7-store-pending-dispatch when the second-stage Dispatch button was emitted.
// Pulls worker, issue context, and dispatch message coordinates needed for
// label verification, prompt assembly, and final editMessageText.
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';

const data = $input.item.json;
const targetToken = data.token;

let content = '';
try {
  if (fs.existsSync(PENDING)) content = fs.readFileSync(PENDING, 'utf8');
} catch (e) {
  return { json: { ...data, found: false, lookup_error: 'pending_callbacks read error: ' + e.message } };
}

const lines = content.split('\n').filter(Boolean);
let dispatchRow = null;
let finalRow = null; // Latest row with kind='dispatch' that ALSO has a final status
for (let i = lines.length - 1; i >= 0; i--) {
  let row;
  try { row = JSON.parse(lines[i]); } catch (e) { continue; }
  if (row.token !== targetToken) continue;
  if (row.kind !== 'dispatch') continue;
  // The most recent dispatch row carries the latest status. We capture it as
  // dispatchRow; if it's already at a terminal status the caller can decide.
  if (!dispatchRow) {
    dispatchRow = row;
  }
  if (!finalRow && (row.status === 'dispatched' || row.status === 'cursor_handoff' || row.status === 'failed')) {
    finalRow = row;
  }
  if (dispatchRow) break;
}

if (!dispatchRow) {
  return { json: { ...data, found: false, lookup_error: 'no kind=dispatch row for token (W7 emit chain may have failed)' } };
}

return { json: {
  ...data,
  found: true,
  trace_id: dispatchRow.trace_id || dispatchRow.token,
  worker: dispatchRow.worker,
  flow: dispatchRow.flow,
  issue_id: dispatchRow.issue_id,
  issue_identifier: dispatchRow.issue_identifier,
  issue_url: dispatchRow.issue_url,
  dispatch_chat_id: dispatchRow.dispatch_chat_id != null ? dispatchRow.dispatch_chat_id : data.chat_id,
  dispatch_message_id: dispatchRow.dispatch_message_id != null ? dispatchRow.dispatch_message_id : data.message_id,
  prompt_path: dispatchRow.prompt_path,
  prior_status: dispatchRow.status,
  prior_dispatched_at: dispatchRow.dispatched_at || null
}};

// w4010-verify-label (PRO-84)
// Confirms the worker label is still attached to the issue. Catches the operator-
// removed-label race: between the Approve tap and the Dispatch tap, the operator
// could have manually removed the worker label in Linear. Aborting here prevents
// dispatching a worker whose label has been retracted.
const prior = $('w4006-lookup-pending-dispatch').item.json;
const resp = $input.item.json;

const issue = resp && resp.data && resp.data.issue;
if (!issue) {
  return { json: { ...prior, label_present: false, label_check_error: 'Linear query returned no issue (errors=' + JSON.stringify(resp && resp.errors || null) + ')' } };
}

const labels = (issue.labels && issue.labels.nodes) || [];
const names = labels.map(l => l.name);
const present = names.includes(prior.worker);

// Also capture the canonical issue url + identifier from Linear in case W7's
// pending row was missing them (defensive).
const issue_url = issue.url || prior.issue_url;
const issue_identifier = issue.identifier || prior.issue_identifier;

if (!present) {
  return { json: { ...prior, label_present: false, label_check_error: 'worker label "' + prior.worker + '" not in issue labels [' + names.join(', ') + ']', issue_url, issue_identifier, current_label_names: names } };
}

return { json: { ...prior, label_present: true, issue_url, issue_identifier, current_label_names: names } };

// w4015-update-pending-cursor (PRO-84)
// Append a pending_callbacks dispatch row marking the cursor handoff completed.
// No prompt JSON written, no listener POST (cursor stays manual per locked decision).
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const prior = $('w4010-verify-label').item.json;
const editResp = $input.item.json;

const row = {
  schema_version: 'v1',
  kind: 'dispatch',
  token: prior.token,
  trace_id: prior.trace_id,
  worker: prior.worker,
  flow: prior.flow,
  issue_id: prior.issue_id,
  issue_identifier: prior.issue_identifier,
  issue_url: prior.issue_url,
  dispatch_chat_id: prior.dispatch_chat_id,
  dispatch_message_id: prior.dispatch_message_id,
  prompt_path: prior.prompt_path,
  status: 'cursor_handoff',
  handed_off_at: new Date().toISOString(),
  edit_message_ok: !(editResp && editResp.error)
};
fs.appendFileSync(PENDING, JSON.stringify(row) + '\n');
return { json: { ...prior, _cursor_handoff_persisted: true } };

// w4021-assemble-prompt (PRO-84)
// Build the prompt JSON object to write at data/n8n_inbox/<trace_id>.json.
// schema_version='v1' per PRO-83 listener contract. The listener reads this file,
// extracts the top-level `prompt` field as a string, and pipes it to the worker on stdin.
// Other top-level fields are audit/replay metadata — not consumed by the listener.
const prior = $('w4010-verify-label').item.json;
const resp = $input.item.json;

const issue = (resp && resp.data && resp.data.issue) || {};
const title = issue.title || '';
const description = issue.description || '';
const url = issue.url || prior.issue_url;
const identifier = issue.identifier || prior.issue_identifier;
const comments = (issue.comments && issue.comments.nodes) || [];

const commentSection = comments.length === 0
  ? '_No comments yet._'
  : comments.map(c => '---\n**' + (c.user && c.user.name ? c.user.name : 'unknown') + '** at ' + (c.createdAt || '?') + '\n\n' + (c.body || '')).join('\n\n');

const worker = prior.worker;
const trace_id = prior.trace_id;

const promptText = [
  'You are working on Linear ticket ' + identifier + ' \u2014 ' + title + '.',
  '',
  'Linear issue URL: ' + url,
  'Trace ID for this dispatch: ' + trace_id,
  '',
  'Before starting work:',
  '- Read CLAUDE.md (project root) for the latest worker rules.',
  '- Read AGENTS.md if present.',
  '- Check for any relevant canon refs the ticket links to.',
  '',
  '## Ticket description',
  '',
  description || '_No description provided._',
  '',
  '## Recent comments',
  '',
  commentSection,
  '',
  '## Completion contract',
  '',
  'When done, end your work with exactly one of:',
  '- STATUS: CONFIRMED WORKING',
  '- STATUS: INCONCLUSIVE',
  '- STATUS: FAILED',
  '',
  'Plus a one-paragraph summary of what changed and what didn\'t.',
  '',
  'Run the hygiene gate (pre-commit run) before opening any PR. Append a row to',
  'data/cc_completion_log.jsonl per the locked convention. Move the Linear ticket',
  'to In Review when ready for operator review (only operator/Claude Chat moves to Done).',
  '',
  'Include the trace ID (' + trace_id + ') in your PR description so it can be correlated',
  'with this dispatch in routing_history.jsonl and the listener trace logs.'
].join('\n');

const promptDoc = {
  schema_version: 'v1',
  trace_id,
  worker,
  ticket_id: prior.issue_id,
  ticket_identifier: identifier,
  ticket_url: url,
  ticket_title: title,
  created_at: new Date().toISOString(),
  prompt: promptText
};

return { json: { ...prior, prompt_doc: promptDoc, prompt_doc_string: JSON.stringify(promptDoc) } };

// w4022-write-prompt-file (PRO-84)
// Write the assembled prompt JSON to /miru-data/n8n_inbox/<trace_id>.json. The host
// path is data/n8n_inbox/<trace_id>.json (mounted at /miru-data inside the n8n
// container per docker-compose volumes block). Matches the listener's INBOX_DIR
// resolution (services/dispatch_listener/src/index.js, REPO_ROOT/data/n8n_inbox).
// Atomic write: temp file + rename, mirrors src/receipt.js convention.
const fs = require('fs');
const path = require('path');
const INBOX_HOST = 'data/n8n_inbox';
const INBOX_CONTAINER = '/miru-data/n8n_inbox';

const data = $input.item.json;
const trace_id = data.trace_id;
const content = data.prompt_doc_string;

try {
  if (!fs.existsSync(INBOX_CONTAINER)) fs.mkdirSync(INBOX_CONTAINER, { recursive: true });
} catch (e) {
  return { json: { ...data, prompt_write_ok: false, prompt_write_error: 'mkdir failed: ' + e.message } };
}

const tmpPath = path.join(INBOX_CONTAINER, trace_id + '.json.tmp');
const finalPath = path.join(INBOX_CONTAINER, trace_id + '.json');

try {
  fs.writeFileSync(tmpPath, content, 'utf8');
  fs.renameSync(tmpPath, finalPath);
} catch (e) {
  try { fs.unlinkSync(tmpPath); } catch (_) { /* best effort */ }
  return { json: { ...data, prompt_write_ok: false, prompt_write_error: 'write/rename failed: ' + e.message } };
}

// prompt_path returned to caller is the HOST-relative path, which is what the
// listener expects (it joins with REPO_ROOT). We do NOT send the container path.
return { json: { ...data, prompt_write_ok: true, prompt_path_host: INBOX_HOST + '/' + trace_id + '.json' } };

// w4023-build-listener-request (PRO-84)
// Serialize the listener request body ONCE and HMAC the exact bytes that will be
// sent. The listener (services/dispatch_listener/src/hmac.js) does HMAC-SHA256
// over the raw request body using W4_LISTENER_HMAC_SECRET, full 64 hex chars,
// constant-time compared via crypto.timingSafeEqual. If n8n re-serializes between
// signing and sending, the HMAC will mismatch — so the HTTP node downstream MUST
// send body_string verbatim (specifyBody:string + body=body_string, NOT a JSON object).
const crypto = require('crypto');
const secret = $env.W4_LISTENER_HMAC_SECRET;
if (!secret || secret.length < 16) {
  return { json: { ...$input.item.json, listener_prep_ok: false, listener_prep_error: 'W4_LISTENER_HMAC_SECRET missing or too short — check docker-compose env passthrough' } };
}

const data = $input.item.json;

const bodyObj = {
  schema_version: 'v1',
  trace_id: data.trace_id,
  worker: data.worker,
  prompt_path: data.prompt_path_host,
  timeout_seconds: 600
};
const body_string = JSON.stringify(bodyObj);
const hmac_hex = crypto.createHmac('sha256', secret).update(body_string).digest('hex');

return { json: { ...data, listener_prep_ok: true, listener_body_string: body_string, listener_hmac_hex: hmac_hex } };

// w4027-update-pending-dispatched (PRO-84)
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const prior = $('w4023-build-listener-request').item.json;

const row = {
  schema_version: 'v1',
  kind: 'dispatch',
  token: prior.token,
  trace_id: prior.trace_id,
  worker: prior.worker,
  flow: prior.flow,
  issue_id: prior.issue_id,
  issue_identifier: prior.issue_identifier,
  issue_url: prior.issue_url,
  dispatch_chat_id: prior.dispatch_chat_id,
  dispatch_message_id: prior.dispatch_message_id,
  prompt_path: prior.prompt_path_host,
  status: 'dispatched',
  dispatched_at: new Date().toISOString()
};
fs.appendFileSync(PENDING, JSON.stringify(row) + '\n');
return { json: { ...prior, _dispatched_persisted: true } };

// w4030-write-dlq (PRO-84)
// Append a DLQ row for genuine failures (401/403/5xx) — deliberately NOT the 409
// branch. 409 is idempotency working as designed (operator double-tap or two W4
// instances raced); treating it as DLQ would pollute calibration data with system-
// correct behavior. See locked design decision §3 in the plan. Schema matches
// services/dispatch_listener/src/dlq.js so consumers can read both sources.
const fs = require('fs');
const DLQ = '/miru-data/dispatch_dlq.jsonl';

const prior = $('w4023-build-listener-request').item.json;
const resp = $input.item.json || {};
const statusCode = resp.statusCode != null ? resp.statusCode : 0;
const respBody = (resp.body && (typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body))) || '';

let error_class;
if (statusCode === 401) error_class = 'hmac_reject_w4_to_listener';
else if (statusCode === 403) error_class = 'allowlist_reject';
else if (statusCode >= 500) error_class = 'listener_5xx';
else if (statusCode === 0) error_class = 'listener_unreachable';
else error_class = 'listener_unexpected_status_' + statusCode;

const row = {
  schema_version: 'v1',
  trace_id: prior.trace_id,
  worker: prior.worker,
  prompt_path: prior.prompt_path_host,
  exit_code: null,
  stderr_tail: respBody.slice(0, 4096),
  error_class,
  timestamp: new Date().toISOString()
};
fs.appendFileSync(DLQ, JSON.stringify(row) + '\n');

return { json: { ...prior, dlq_written: true, dlq_error_class: error_class, dlq_status_code: statusCode, dlq_response_body: respBody.slice(0, 1024) } };
